export const RELATION_DOMAIN_CONTRACT=Object.freeze({id:'RelationDomainAdapter',version:'1.2.0',compatibility:'SEMVER'});
/** Domain adapter owns canonical relation records. SpatialModel only projects them. */
export class RelationDomainAdapter {
 constructor({owner,nodes,relations=[],types=['relates','depends','connects'],validate=()=>{},fields=[],readOnly=false,relationEligible=null,bulkRelationSemantics=null,capabilities=null}){Object.assign(this,{owner,nodes,types,validate,fields,readOnly,relationEligible,bulkRelationSemantics});this.capabilities={relationAuthoring:!readOnly,...capabilities};this.contract=RELATION_DOMAIN_CONTRACT;this.records=structuredClone(relations);this.version=1;this.history=[];this.future=[];this.listeners=new Set();}
 subscribe(fn){this.listeners.add(fn);return ()=>this.listeners.delete(fn)}
 emit(){for(const fn of this.listeners)fn(this.project())}
 project(){return this.records.map(r=>({...structuredClone(r),canonicalId:r.id,canonicalVersion:this.version,kind:'domain-projection'}))}
 connectionAvailability(ids,activeMode='author'){
  if(this.readOnly)return {enabled:false,reason:'Relationship source is read only',code:'READ_ONLY'};
  if(activeMode!=='author')return {enabled:false,reason:'Active mode does not permit relation authoring',code:'MODE'};
  if(this.capabilities.relationAuthoring===false)return {enabled:false,reason:'Relationship authoring capability is disabled',code:'CAPABILITY'};
  const bulk=ids.length>2&&this.bulkRelationSemantics?.deterministic===true;
  if(ids.length>2&&!bulk)return {enabled:false,reason:'Bulk relation semantics are not defined',code:'BULK_UNDEFINED'};
  if(ids.length!==2&&!bulk)return {enabled:false,reason:'Select exactly two endpoints',code:'COUNT'};
  const endpoints=ids.map(id=>this.nodes.find(node=>node.id===id));if(endpoints.some(x=>!x))return {enabled:false,reason:'Selection contains an unknown endpoint',code:'UNKNOWN_ENDPOINT'};
  if(ids.length===2&&ids[0]===ids[1])return {enabled:false,reason:'A relation requires distinct endpoints',code:'SAME_ENDPOINT'};
  if(ids.length===2&&this.records.some(record=>(record.source===ids[0]&&record.target===ids[1])||(record.source===ids[1]&&record.target===ids[0])))return {enabled:false,reason:'A canonical relationship already exists between these endpoints',code:'DUPLICATE_CANONICAL_RELATION'};
  const eligible=this.relationEligible?.({ids,endpoints,types:[...this.types],version:this.version,canonicalRelations:this.project()});if(eligible===false)return {enabled:false,reason:'Selected endpoint types are incompatible',code:'INCOMPATIBLE_ENDPOINT_TYPES'};if(typeof eligible==='string')return {enabled:false,reason:eligible,code:'DOMAIN_COMPATIBILITY'};
  return {enabled:this.types.length>0,reason:this.types.length?'':'No relation type is available',code:this.types.length?'AVAILABLE':'NO_RELATION_TYPE'};
 }
 commit(p){if(this.readOnly)throw Error('RECORDED_RELATIONS_READ_ONLY');if(p.expectedVersion!==this.version)throw Error('STALE_RELATION_VERSION');if(!this.nodes.some(n=>n.id===p.source)||!this.nodes.some(n=>n.id===p.target)||p.source===p.target)throw Error('INVALID_ENDPOINTS');if(!this.types.includes(p.type))throw Error('INVALID_RELATION_TYPE');if(!['directed','bidirectional'].includes(p.direction))throw Error('INVALID_DIRECTION');if(p.id&&!this.records.some(r=>r.id===p.id))throw Error('UNKNOWN_RELATION');if(!p.id&&this.records.some(record=>(record.source===p.source&&record.target===p.target)||(record.source===p.target&&record.target===p.source)))throw Error('DUPLICATE_CANONICAL_RELATION');const extra=this.validate(p)||{};let i=1;while(this.records.some(r=>r.id===`relation-${i}`))i++;const r={id:p.id||`relation-${i}`,source:p.source,target:p.target,type:p.type,direction:p.direction,...Object.fromEntries(this.fields.map(f=>[f.name,String(p[f.name]||'')])),...extra};this.history.push(structuredClone(this.records));this.future=[];if(p.id)this.records=this.records.map(x=>x.id===p.id?r:x);else this.records.push(r);this.version++;this.emit();return structuredClone(r)}
 reverseAvailability(id,activeMode='author'){if(this.readOnly)return {enabled:false,reason:'Relationship source is read only',code:'READ_ONLY'};if(activeMode!=='author')return {enabled:false,reason:'Active mode does not permit relation authoring',code:'MODE'};if(this.capabilities.relationAuthoring===false)return {enabled:false,reason:'Relationship authoring capability is disabled',code:'CAPABILITY'};const relation=this.records.find(record=>record.id===id);if(!relation)return {enabled:false,reason:'Select an editable relationship',code:'UNKNOWN_RELATION'};const payload={...structuredClone(relation),source:relation.target,target:relation.source,direction:relation.direction||'directed',expectedVersion:this.version};try{if(!this.nodes.some(node=>node.id===payload.source)||!this.nodes.some(node=>node.id===payload.target)||payload.source===payload.target)throw Error('INVALID_ENDPOINTS');if(!this.types.includes(payload.type))throw Error('INVALID_RELATION_TYPE');if(!['directed','bidirectional'].includes(payload.direction))throw Error('INVALID_DIRECTION');this.validate(payload);return {enabled:true,reason:'',code:'AVAILABLE',payload};}catch(error){return {enabled:false,reason:String(error?.message||error),code:'DOMAIN_REVERSE_CONSTRAINT'};}}
 reverse(id,expectedVersion=this.version){if(this.readOnly)throw Error('RECORDED_RELATIONS_READ_ONLY');if(expectedVersion!==this.version)throw Error('STALE_RELATION_VERSION');const availability=this.reverseAvailability(id);if(!availability.enabled)throw Error(availability.reason);return this.commit(availability.payload);}
 undo(){return this.restore(this.history,this.future)}
 redo(){return this.restore(this.future,this.history)}
 restore(from,to){if(this.readOnly)throw Error('RECORDED_RELATIONS_READ_ONLY');const frame=from.pop();if(!frame)return false;to.push(structuredClone(this.records));this.records=frame;this.version++;this.emit();return true}
}

export {RELATION_INTERACTION_OWNER_ID,RELATION_INTERACTION_CONTRACT,RelationInteractionOwner,RelationInteractionOwner as RelationInteraction} from './spatial/relation-interaction.js';
